const UNDO_LIMIT = 40;
const undoStack = [];
/* 恢复栈：撤销时把当前状态压进来；任何新的可撤销操作都会清空它（与常见编辑器一致） */
const redoStack = [];
let undoSuppressed = false;
let pendingUndoSnapshot = null;
let runningHubWorkflowCache = {};
function activeSmartCascadeCount(){ return smartCascadeRuns.size; }
function smartCascadeRunForLoop(loopId){ return loopId ? smartCascadeRuns.get(loopId) || null : null; }
function smartCascadeIsLoopRunning(loopId){ return Boolean(smartCascadeRunForLoop(loopId)); }
function syncSmartCascadeLegacyState(preferredLoopId=''){
    const activeIds = [...smartCascadeRuns.keys()];
    smartCascadeRunning = activeIds.length > 0;
    smartCascadeActiveLoopId = preferredLoopId && smartCascadeRuns.has(preferredLoopId)
        ? preferredLoopId
        : (activeIds[0] || '');
    const activeRun = smartCascadeActiveLoopId ? smartCascadeRuns.get(smartCascadeActiveLoopId) : null;
    smartCascadeStopRequested = Boolean(activeRun?.stopRequested);
    smartCascadeRunPath = activeRun?.runPath || null;
}
function smartCascadeAnyRunning(){ return smartCascadeRunning || activeSmartCascadeCount() > 0; }
function smartCascadeEdgeState(edgeKey){
    for(const run of smartCascadeRuns.values()){
        const state = run?.runPath?.states?.[edgeKey];
        if(state) return state;
    }
    return smartCascadeRunPath?.states?.[edgeKey] || '';
}
function smartCascadePathForCtx(ctx=null){
    return ctx?.runState?.runPath || ctx?.runPath || smartCascadeRunPath;
}
function capturePendingUndo(){ pendingUndoSnapshot = snapshotForUndo(); }
function commitPendingUndo(){
    if(pendingUndoSnapshot){
        undoStack.push(pendingUndoSnapshot);
        if(undoStack.length > UNDO_LIMIT) undoStack.shift();
        redoStack.length = 0;
        pendingUndoSnapshot = null;
    }
}
function discardPendingUndo(){ pendingUndoSnapshot = null; }
/* 撤销快照做「结构共享」：每个节点序列化后跟上一次快照里同 id 的比较，内容没变就直接复用那份只读副本，
   只对真的变了的节点重新 parse。40 步撤销里绝大多数节点是同一份对象，内存从「40 份全量」降到「1 份 + 改动」，
   每次 pushUndo 也省掉了大部分 JSON.parse。快照里的对象是共享的，所以恢复时必须再拷一份给画布用（见 thawUndoSnapshot）。 */
let undoNodeCache = new Map();
let undoConnCache = {json:'', value:[]};
function freezeUndoNodes(list){
    const next = new Map();
    const out = (list || []).map(node => {
        const json = JSON.stringify(node);
        const key = node && node.id != null ? String(node.id) : '';
        const hit = key ? undoNodeCache.get(key) : null;
        const value = hit && hit.json === json ? hit.value : JSON.parse(json);
        if(key) next.set(key, {json, value});
        return value;
    });
    undoNodeCache = next;
    return out;
}
function freezeUndoConnections(list){
    const json = JSON.stringify(list || []);
    if(json !== undoConnCache.json) undoConnCache = {json, value:JSON.parse(json)};
    return undoConnCache.value;
}
function snapshotForUndo(){
    return {
        nodes: freezeUndoNodes(nodes),
        connections: freezeUndoConnections(canvas?.connections || []),
        selectedId,
        selectedIds: selectedIds.slice(),
        selectedImage: {...selectedImage}
    };
}
/* 快照里的节点和连线在多个快照之间共享，交给画布前拷一份，画布后续的原地修改不会改到历史 */
function thawUndoSnapshot(snap){
    return {
        ...snap,
        nodes: JSON.parse(JSON.stringify(snap.nodes || [])),
        connections: JSON.parse(JSON.stringify(snap.connections || [])),
        selectedIds: (snap.selectedIds || []).slice(),
        selectedImage: {...(snap.selectedImage || {})}
    };
}
function pushUndo(){
    if(undoSuppressed) return;
    if(!canvas) return;
    undoStack.push(snapshotForUndo());
    if(undoStack.length > UNDO_LIMIT) undoStack.shift();
    redoStack.length = 0;
}
function restoreUndoSnapshot(frozen){
    const snap = thawUndoSnapshot(frozen);
    undoSuppressed = true;
    nodes = snap.nodes;
    if(canvas) canvas.connections = snap.connections;
    selectedId = snap.selectedId;
    selectedIds = snap.selectedIds;
    selectedImage = snap.selectedImage;
    activeComposerSubject = null;
    lastComposerNodeId = '';
    render();
    scheduleSave();
    undoSuppressed = false;
}
function performRedo(){
    if(collabReadOnly){ collabNotifyReadOnly(); return; }
    if(!redoStack.length){ toast(tr('smart.toastNoRedo')); return; }
    const snap = redoStack.pop();
    undoStack.push(snapshotForUndo());
    if(undoStack.length > UNDO_LIMIT) undoStack.shift();
    restoreUndoSnapshot(snap);
    toast(tr('smart.toastRedone'));
}
function performUndo(){
    if(collabReadOnly){ collabNotifyReadOnly(); return; }
    if(!undoStack.length){ toast(tr('smart.toastNoUndo')); return; }
    const snap = thawUndoSnapshot(undoStack.pop());
    redoStack.push(snapshotForUndo());
    if(redoStack.length > UNDO_LIMIT) redoStack.shift();
    undoSuppressed = true;
    nodes = snap.nodes;
    if(canvas) canvas.connections = snap.connections;
    selectedId = snap.selectedId;
    selectedIds = snap.selectedIds;
    selectedImage = snap.selectedImage;
    activeComposerSubject = null;
    lastComposerNodeId = '';
    render();
    scheduleSave();
    undoSuppressed = false;
    toast(tr('smart.toastUndone'));
}
