        square: {'0.5k': '512x512'}, portrait14: {'0.5k': '256x1024'}, portrait18: {'0.5k': '192x1536'},
        portrait: {'0.5k': '424x632'}, landscape: {'0.5k': '632x424'}, portrait43: {'0.5k': '448x600'},
