function clampZoomBarScale(value){
    const n = Number(value);
    if(!Number.isFinite(n) || n <= 0) return 1;
    return Math.max(ZOOM_BAR_MIN_SCALE, Math.min(ZOOM_BAR_MAX_SCALE, n));
}
function updateZoomBarLevel(){
    const label = document.getElementById('canvasZoomLevel');
    if(!label) return;
    label.textContent = `${Math.round((viewport.scale || 1) * 100)}%`;
}
// 以可视区中心为锚点缩放，避免内容跳走。
function zoomBarApplyScale(nextScale){
    const target = clampZoomBarScale(nextScale);
    const oldScale = viewport.scale || 1;
    if(Math.abs(target - oldScale) < 1e-6){
        updateZoomBarLevel();
        return;
    }
    const rect = shell.getBoundingClientRect();
    const cx = rect.width / 2;
    const cy = rect.height / 2;
    viewport.x = cx - (cx - viewport.x) * (target / oldScale);
    viewport.y = cy - (cy - viewport.y) * (target / oldScale);
    viewport.scale = target;
    applyViewport();
    scheduleViewportSave();
}
function zoomBarZoomIn(){
    zoomBarApplyScale(Math.round((viewport.scale || 1) * 100 + 5) / 100);
}
function zoomBarZoomOut(){
    zoomBarApplyScale(Math.round((viewport.scale || 1) * 100 - 5) / 100);
}
function zoomBarReset(){
    zoomBarApplyScale(1);
}
function zoomBarFitAll(){
    fitAllNodesViewport();
    updateZoomBarLevel();
}
function zoomBarCenter(){
    const pool = selectedNodeIds().length
        ? nodes.filter(n => selectedNodeIds().includes(n.id))
        : nodes;
    if(!pool.length) return;
    const rects = pool.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    const maxX = Math.max(...rects.map(r => r.x + r.width));
    const maxY = Math.max(...rects.map(r => r.y + r.height));
    centerViewportOnWorldPoint({x:(minX + maxX) / 2, y:(minY + maxY) / 2});
    updateZoomBarLevel();
}
function enterZoomPreview(){
    if(zoomPreviewState) return;
    zoomPreviewState = {...viewport};
    shell.classList.add('zoom-preview');
    closeCreateMenu();
    fitAllNodesViewport();
}
function exitZoomPreview(point=null){
    if(!zoomPreviewState) return false;
    const prev = zoomPreviewState;
    zoomPreviewState = null;
    shell.classList.remove('zoom-preview');
    viewport.scale = prev.scale;
    if(point){
        viewport.x = shell.clientWidth / 2 - point.x * viewport.scale;
        viewport.y = shell.clientHeight / 2 - point.y * viewport.scale;
    } else {
        viewport.x = prev.x;
        viewport.y = prev.y;
    }
    applyViewport();
    scheduleViewportSave();
    return true;
}
function exitZoomPreviewToNode(nodeId){
    if(!zoomPreviewState) return false;
    const node = nodes.find(n => n.id === nodeId);
    if(!node) return exitZoomPreview();
    const prev = zoomPreviewState;
    const rect = nodeRect(node);
    const cx = rect.x + rect.width / 2;
    const cy = rect.y + rect.height / 2;
    const fitW = Math.max(1, shell.clientWidth - 160);
    const fitH = Math.max(1, shell.clientHeight - 160);
    const fitScale = Math.min(
        ZOOM_PREVIEW_NODE_MAX_SCALE,
        fitW / Math.max(1, rect.width),
        fitH / Math.max(1, rect.height)
    );
    const readableScale = Math.min(ZOOM_PREVIEW_NODE_MAX_SCALE, Math.max(ZOOM_PREVIEW_NODE_DEFAULT_SCALE, fitScale));
    zoomPreviewState = null;
    shell.classList.remove('zoom-preview');
    viewport.scale = Math.max(safeScale(prev.scale), readableScale);
    viewport.x = shell.clientWidth / 2 - cx * viewport.scale;
    viewport.y = shell.clientHeight / 2 - cy * viewport.scale;
    applyViewport();
    scheduleViewportSave();
    return true;
}
function toggleZoomPreview(){
    if(zoomPreviewState) exitZoomPreview();
    else enterZoomPreview();
}
