    if(run?.kind === 'audio') return {provider_id:s.audioProvider || '', model:s.audioModel || '', duration:s.audioDuration || '', length:s.audioLength || '', bpm:s.audioBpm || '', format:s.audioFormat || '', instrumental:Boolean(s.audioInstrumental)};
